BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_sync_operations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,client_operation_id TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('create','update','checkin')),base_version INTEGER NOT NULL DEFAULT 0,payload JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'applied',server_version INTEGER NOT NULL,applied_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id,client_operation_id));
CREATE TABLE IF NOT EXISTS mission_bridge_sync_conflicts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,client_operation_id TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,client_version INTEGER NOT NULL,server_version INTEGER NOT NULL,resolution TEXT NOT NULL DEFAULT 'manual_required',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE mission_bridge_sync_operations ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON mission_bridge_sync_operations USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));ALTER TABLE mission_bridge_sync_conflicts ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON mission_bridge_sync_conflicts USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
COMMIT;
